ST.xhtml:p:
RTrigger1(CLK := bSustain1AbsOpen OR g_bSustainAxis1RelMoveEnableM);
RTrigger2(CLK := bSustain1AbsClose);
RTrigger3(CLK := bSustain2AbsOpen OR g_bSustainAxis2RelMoveEnableM);
RTrigger4(CLK := bSustain2AbsClose);
RTrigger5(CLK := bSustain3AbsOpen OR g_bSustainAxis3RelMoveEnableM);
RTrigger6(CLK := bSustain3AbsClose);
