RTrigger14(CLK := g_bAxisStopFlag_5 OR g_bAxisStopFlag_6 OR g_bAxisStopFlag_7 OR g_bAxisStopFlag_8 OR g_bAxisStopFlag_9 OR g_bAxisStopFlag_10);

IF RTrigger1.Q THEN
  nSustain1RelState := 1;
  g_bSustain1AbsDone := FALSE;
  IF bSustain1AbsOpen THEN
    dSustain1RelMoceDistance := dDistance;
     bSustain1AbsOpen := FALSE;
     IF g_bFastInch=0 THEN
      dTargetAxis1Vel := dSustain1AxisSlowVel;
    ELSE
      dTargetAxis1Vel := dSustain1AxisFastVel;
    END_IF;
  ELSIF g_bSustainAxis1RelMoveEnableM THEN
    dSustain1RelMoceDistance := g_dSustainAxisMoveDistanceM;
    g_bSustainAxis1RelMoveEnableM := FALSE;
    IF g_bSetAuxiliaryAxisSpeed THEN
      dTargetAxis1Vel := g_nAuxiliaryAxisSpeed;
      g_bSetAuxiliaryAxisSpeed := FALSE;
    ELSE
      dTargetAxis1Vel := dSustain1AutoVel;
    END_IF;
    IF g_fCurrentCoordYBuffer >= (g_fSupAxisCoordY1 - g_fSupAxisDownDis1) THEN
       g_bSustain1AbsDone := TRUE;
      g_bSustainAxis1MoveDoneM320 := TRUE;
      nSustain1RelState := 0;
      g_bExecuteFinishedM306 := FALSE;
      g_bFinishedM306_1 := FALSE;
    END_IF;
  END_IF;
  (*IF nSustain1RelState <> 0  AND nSustain1RelState <> 20 AND Axis_Sustain1.NCTOPLC.ACTVELO > g_dCheckAxisIsMovingSpeedSet  THEN
    g_bAxisIsMoveAlarm := TRUE;
    bSustain1AbsOpen := FALSE;
    g_bSustainAxis1RelMoveEnableM := FALSE;
  nSustain1RelState := 21;
  END_IF;*)
END_IF;

IF RTrigger2.Q THEN
  g_bSustain1AbsDone := FALSE;
END_IF;

