CASE nSustain1RelState OF
  0:
    nSustain1RelState := 0;
  1:
    g_Sustain1Abs.Execute := TRUE;
    g_Sustain1Abs.Velocity := dTargetAxis1Vel;
    g_Sustain1Abs.Position := Axis_Sustain1.NCTOPLC.SETPOS + dSustain1RelMoceDistance;
    IF g_Sustain1Abs.Done THEN
      g_Sustain1Abs.Execute := FALSE;
      g_bSustain1AbsDone := TRUE;
      g_bSustainAxis1MoveDoneM320 := TRUE;
      nSustain1RelState := 0;
      g_bExecuteFinishedM306 := FALSE;
      g_bFinishedM306_1 := FALSE;
    END_IF;
    IF g_bPlcPauseBuffer THEN
      nSustain1RelState := 20;
    END_IF;
    IF g_Sustain1Abs.CommandAborted OR g_Sustain1Abs.Error THEN
      g_Sustain1Abs.Execute := FALSE;
      g_bSustain1AbsDone := FALSE;
      nSustain1RelState := 0;
      M.ENABLE[306] := 0;
      g_bExecuteFinishedM306 := FALSE;
      g_bFinishedM306_1 := FALSE;
    END_IF;
  20:
    g_Sustain1Abs.Execute := FALSE;
    g_Sustain1Stop.Execute := TRUE;
    IF g_Sustain1Stop.Done AND g_bPlcStartBuffer THEN
      g_Sustain1Stop.Execute := FALSE;
      nSustain1RelState := 1;
      g_bSustainAxis1MoveDoneM320 := TRUE;
    END_IF;
    IF g_Sustain1Stop.CommandAborted OR g_Sustain1Stop.Error THEN
      g_Sustain1Stop.Execute := FALSE;
      nSustain1RelState := 0;
      M.ENABLE[306] := 0;
      g_bExecuteFinishedM306 := FALSE;
      g_bFinishedM306_1 := FALSE;
    END_IF;
  21:
    g_Sustain1Abs.Execute := FALSE;
    g_Sustain1Stop.Execute := TRUE;
    IF g_Sustain1Stop.Done THEN
      g_Sustain1Stop.Execute := FALSE;
      g_bFinishedM325_5 := FALSE;
      M.ENABLE[325] := 0;
      nSustain1RelState := 0;
      g_bSustainAxis1MoveDoneM320 := TRUE;
    END_IF;
    IF g_Sustain1Stop.CommandAborted OR g_Sustain1Stop.Error THEN
      g_Sustain1Stop.Execute := FALSE;
      g_bFinishedM325_5 := FALSE;
      M.ENABLE[325] := 0;
      nSustain1RelState := 0;
      M.ENABLE[306] := 0;
      g_bExecuteFinishedM306 := FALSE;
      g_bFinishedM306_1 := FALSE;
    END_IF;
END_CASE;

