      g_bSustainAxis6MoveDoneM320 := TRUE;
      nSustain9RelState := 0;
      g_bExecuteFinishedM306 := FALSE;
      g_bFinishedM306_6 := FALSE;
    END_IF;
    IF g_bPlcPauseBuffer THEN
      nSustain9RelState := 20;
    END_IF;
    IF g_Sustain9Abs.CommandAborted OR g_Sustain9Abs.Error THEN
      g_Sustain9Abs.Execute := FALSE;
      g_bSustain9AbsDone := FALSE;
      nSustain9RelState := 0;
      g_bExecuteFinishedM306 := FALSE;
      g_bFinishedM306_6 := FALSE;
    END_IF;
  20:
    g_Sustain9Abs.Execute := FALSE;
    g_Sustain9Stop.Execute := TRUE;
    IF g_Sustain9Stop.Done AND g_bPlcStartBuffer THEN
      g_Sustain9Stop.Execute := FALSE;
      nSustain9RelState := 1;
    END_IF;
    IF g_Sustain9Stop.CommandAborted OR g_Sustain9Stop.Error THEN
      g_Sustain9Stop.Execute := FALSE;
      nSustain9RelState := 0;
      M.ENABLE[306] := 0;
      g_bExecuteFinishedM306 := FALSE;
      g_bFinishedM306_6 := FALSE;
    END_IF;
  21:
    g_Sustain9Abs.Execute := FALSE;
    g_Sustain9Stop.Execute := TRUE;
    IF g_Sustain9Stop.Done THEN
      g_Sustain9Stop.Execute := FALSE;
      g_bFinishedM325_10 := FALSE;
      M.ENABLE[325] := 0;
      nSustain9RelState := 0;
      g_bSustainAxis6MoveDoneM320 := TRUE;
    END_IF;
    IF g_Sustain9Stop.CommandAborted OR g_Sustain9Stop.Error THEN
      g_Sustain9Stop.Execute := FALSE;
      g_bFinishedM325_10 := FALSE;
      M.ENABLE[325] := 0;
      nSustain9RelState := 0;
      M.ENABLE[306] := 0;
      g_bExecuteFinishedM306 := FALSE;
      g_bFinishedM306_6 := FALSE;
    END_IF;
END_CASE;

IF g_bPlcResetBuffer THEN
  nSustain1RelState := 0;
  nSustain2RelState := 0;
  nSustain3RelState := 0;
  nSustain7RelState := 0;
  nSustain8RelState := 0;
  nSustain9RelState := 0;
  g_Sustain1Abs.Execute := FALSE;
  g_Sustain2Abs.Execute := FALSE;
  g_Sustain3Abs.Execute := FALSE;
  g_Sustain7Abs.Execute := FALSE;
  g_Sustain8Abs.Execute := FALSE;
  g_Sustain9Abs.Execute := FALSE;
  g_Sustain1Stop.Execute := FALSE;
  g_Sustain2Stop.Execute := FALSE;
  g_Sustain3Stop.Execute := FALSE;
  g_Sustain7Stop.Execute := FALSE;
  g_Sustain8Stop.Execute := FALSE;
  g_Sustain9Stop.Execute := FALSE;
  g_bExecuteFinishedM306 := FALSE;
  g_bFinishedM325_5 := FALSE;
  g_bFinishedM325_6 := FALSE;
  g_bFinishedM325_7 := FALSE;
  g_bFinishedM325_8 := FALSE;
  g_bFinishedM325_9 := FALSE;
  g_bFinishedM325_10 := FALSE;
END_IF;
